custom_css:
.sc-tw :root{
  --titanium-base: oklch(14% 0.012 250);
  --titanium-mid: oklch(20% 0.02 250);
  --titanium-high: oklch(28% 0.025 250);
  --titanium-edge: oklch(38% 0.02 250);
  --titanium-sheen: oklch(72% 0.01 250);
  --amber: oklch(72% 0.18 85);
  --amber-dim: oklch(60% 0.14 85);
  --amber-glow: oklch(78% 0.2 88 / 0.35);
  --cyan: oklch(68% 0.16 220);
  --cyan-dim: oklch(55% 0.12 220);
  --cyan-glow: oklch(68% 0.16 220 / 0.3);
  --text-primary: oklch(94% 0.005 250);
  --text-secondary: oklch(56% 0.015 250);
  --text-tertiary: oklch(38% 0.015 250);
  --glass-fill: oklch(100% 0 0 / 0.03);
  --glass-border: oklch(100% 0 0 / 0.07);
  --glass-border-bright: oklch(100% 0 0 / 0.14);
  --void: oklch(7% 0.01 250);
}.sc-tw *,.sc-tw *::before,.sc-tw *::after{ box-sizing: border-box; margin: 0; padding: 0; }.sc-tw html{
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: oklch(25% 0.02 250) transparent;
}.sc-tw{
  font-family: 'Inter Tight', sans-serif;
  background: var(--void);
  color: var(--text-primary);
  overflow-x: hidden;
  cursor: none;
  min-height: 100vh;
}.sc-tw .cursor-dot{
  position: fixed;
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--amber);
  pointer-events: none;
  z-index: 9999;
  transform: translate(-50%, -50%);
  transition: width .2s, height .2s, background .2s;
  box-shadow: 0 0 12px 3px var(--amber-glow);
  mix-blend-mode: plus-lighter;
}.sc-tw .cursor-ring{
  position: fixed;
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid oklch(68% 0.16 220 / 0.5);
  pointer-events: none;
  z-index: 9998;
  transform: translate(-50%, -50%);
  transition: transform .14s cubic-bezier(.25,.46,.45,.94), width .3s, height .3s, border-color .3s;
  mix-blend-mode: plus-lighter;
}.sc-tw .cursor-ring.expanded{ width: 56px; height: 56px; border-color: var(--amber); }.sc-tw .noise{
  position: fixed;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0.028;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 512 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 512px 512px;
}.sc-tw .ambient-orb{
  position: fixed;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(120px);
  z-index: 0;
}.sc-tw .orb-amber{
  width: 700px; height: 700px;
  background: oklch(65% 0.16 85 / 0.07);
  top: -200px; right: -100px;
  animation: orb-float-a 18s ease-in-out infinite;
}.sc-tw .orb-cyan{
  width: 500px; height: 500px;
  background: oklch(60% 0.14 220 / 0.07);
  bottom: 10%; left: -100px;
  animation: orb-float-b 22s ease-in-out infinite;
}

@keyframes orb-float-a {0%,100%{ transform: translate(0,0) scale(1); }33%{ transform: translate(-40px, 60px) scale(1.08); }66%{ transform: translate(30px, -40px) scale(0.94); }
}

@keyframes orb-float-b {0%,100%{ transform: translate(0,0) scale(1); }50%{ transform: translate(60px, -50px) scale(1.1); }
}.sc-tw .vault-portal{
  position: fixed;
  top: 0; right: 0;
  width: 48vw;
  height: 100vh;
  z-index: 1;
  pointer-events: none;
  transform: perspective(1200px) rotateY(-4deg) rotateX(1deg);
  transform-origin: right center;
}.sc-tw .vault-video{
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 1;
  filter: none;
  mask: none;
  -webkit-mask: none;
}.sc-tw .light-corridor{
  position: fixed;
  top: 0; right: 0;
  width: 52vw;
  height: 100vh;
  background: transparent;
  backdrop-filter: none;
  pointer-events: none;
  z-index: 2;
  mix-blend-mode: normal;
}.sc-tw .vault-edge-flare{
  position: fixed;
  top: 0;
  left: calc(52vw - 2px);
  width: 180px;
  height: 100vh;
  background: linear-gradient(90deg, transparent, oklch(72% 0.18 85 / 0.06) 30%, oklch(68% 0.16 220 / 0.08) 60%, transparent);
  pointer-events: none;
  z-index: 3;
  filter: blur(2px);
}.sc-tw nav{
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.4rem 3.5rem;
  background: oklch(7% 0.01 250 / 0.75);
  backdrop-filter: blur(32px) saturate(1.3);
  border-bottom: 1px solid var(--glass-border);
}.sc-tw .nav-logo{
  display: flex;
  align-items: center;
  gap: 0.75rem;
}.sc-tw .nav-apple{
  font-size: 1.3rem;
  line-height: 1;
  color: var(--text-primary);
  font-weight: 300;
}.sc-tw .nav-divider{
  width: 1px;
  height: 16px;
  background: var(--glass-border-bright);
}.sc-tw .nav-product{
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  text-transform: uppercase;
  font-family: 'JetBrains Mono', monospace;
}.sc-tw .nav-links{
  display: flex;
  gap: 2.8rem;
  list-style: none;
}.sc-tw .nav-links a{
  font-size: 0.68rem;
  font-weight: 400;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  text-decoration: none;
  font-family: 'JetBrains Mono', monospace;
  transition: color .25s;
}.sc-tw .nav-links a:hover{ color: var(--text-secondary); }.sc-tw .nav-cta{
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--amber);
  font-family: 'JetBrains Mono', monospace;
  cursor: none;
  background: none;
  border: 1px solid oklch(72% 0.18 85 / 0.25);
  padding: 0.5rem 1.2rem;
  border-radius: 2px;
  transition: background .3s, border-color .3s, box-shadow .3s;
}.sc-tw .nav-cta:hover{
  background: oklch(72% 0.18 85 / 0.08);
  border-color: oklch(72% 0.18 85 / 0.5);
  box-shadow: 0 0 20px 4px var(--amber-glow);
}.sc-tw .content-rail{
  position: relative;
  z-index: 10;
  width: 52vw;
  max-width: 780px;
  padding: 0 3.5rem;
}.sc-tw .hero-section{
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 7rem;
  padding-bottom: 4rem;
}.sc-tw .hero-eyebrow{
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 2.2rem;
  opacity: 0;
  animation: reveal-up .9s cubic-bezier(.16,1,.3,1) .2s forwards;
}.sc-tw .eyebrow-line{
  width: 2.5rem;
  height: 1px;
  background: linear-gradient(90deg, var(--amber), transparent);
}.sc-tw .eyebrow-text{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.6rem;
  font-weight: 400;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--amber-dim);
}.sc-tw .hero-title{
  font-family: 'Playfair Display', serif;
  font-size: clamp(3.2rem, 5.5vw, 5.8rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.02em;
  margin-bottom: 1.2rem;
  opacity: 0;
  animation: reveal-up 1s cubic-bezier(.16,1,.3,1) .35s forwards;
}.sc-tw .hero-title em{
  font-style: italic;
  color: var(--amber);
  font-weight: 300;
}.sc-tw .hero-title .line-thin{
  font-weight: 300;
  color: var(--text-secondary);
  font-size: 0.65em;
  display: block;
  letter-spacing: 0.04em;
  font-family: 'Inter Tight', sans-serif;
  font-style: normal;
  margin-top: 0.4em;
}.sc-tw .hero-sub{
  font-size: 0.88rem;
  line-height: 1.8;
  color: var(--text-secondary);
  font-weight: 300;
  max-width: 46ch;
  margin-bottom: 3rem;
  opacity: 0;
  animation: reveal-up .9s cubic-bezier(.16,1,.3,1) .5s forwards;
}.sc-tw .hero-actions{
  display: flex;
  gap: 1rem;
  align-items: center;
  margin-bottom: 5rem;
  opacity: 0;
  animation: reveal-up .9s cubic-bezier(.16,1,.3,1) .65s forwards;
}.sc-tw .btn-primary{
  position: relative;
  padding: 0.9rem 2.4rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--void);
  background: linear-gradient(135deg, var(--amber), oklch(65% 0.16 75));
  border: none;
  border-radius: 3px;
  cursor: none;
  overflow: hidden;
  transition: box-shadow .35s, transform .2s;
}.sc-tw .btn-primary::before{
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at var(--bx,50%) var(--by,50%), oklch(100% 0 0 / 0.3) 0%, transparent 65%);
  opacity: 0;
  transition: opacity .3s;
}.sc-tw .btn-primary:hover{
  box-shadow: 0 0 40px 8px var(--amber-glow), 0 8px 32px oklch(0% 0 0 / 0.4);
  transform: translateY(-1px);
}.sc-tw .btn-primary:hover::before{ opacity: 1; }.sc-tw .btn-secondary{
  position: relative;
  padding: 0.9rem 2rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.68rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-secondary);
  background: var(--glass-fill);
  border: 1px solid var(--glass-border);
  border-radius: 3px;
  cursor: none;
  transition: color .3s, border-color .3s, background .3s;
}.sc-tw .btn-secondary:hover{
  color: var(--text-primary);
  border-color: var(--glass-border-bright);
  background: oklch(100% 0 0 / 0.05);
}.sc-tw .hero-stat-row{
  display: flex;
  gap: 3rem;
  padding-top: 2.5rem;
  border-top: 1px solid var(--glass-border);
  opacity: 0;
  animation: reveal-up .9s cubic-bezier(.16,1,.3,1) .8s forwards;
}.sc-tw .stat-item{}.sc-tw .stat-value{
  font-family: 'Playfair Display', serif;
  font-size: 2.4rem;
  font-weight: 400;
  letter-spacing: -0.03em;
  color: var(--text-primary);
  line-height: 1;
}.sc-tw .stat-value span{
  font-family: 'Inter Tight', sans-serif;
  font-size: 1rem;
  font-weight: 300;
  color: var(--amber);
}.sc-tw .stat-label{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-top: 0.4rem;
}

@keyframes reveal-up {from{ opacity: 0; transform: translateY(24px); }to{ opacity: 1; transform: translateY(0); }
}.sc-tw .anodized-section{
  padding: 8rem 0;
}.sc-tw .section-label{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  font-weight: 400;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--amber-dim);
  margin-bottom: 1.8rem;
  display: flex;
  align-items: center;
  gap: 0.8rem;
}.sc-tw .section-label::before{
  content: '';
  display: block;
  width: 1.5rem;
  height: 1px;
  background: var(--amber-dim);
}.sc-tw .section-title{
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 3.5vw, 3.2rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.05;
  margin-bottom: 1rem;
}.sc-tw .section-title em{ font-style: italic; color: var(--amber); }.sc-tw .anodized-grid{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--glass-border);
  border: 1px solid var(--glass-border);
  border-radius: 6px;
  overflow: hidden;
  margin-top: 3.5rem;
}.sc-tw .anodized-cell{
  position: relative;
  background: var(--titanium-base);
  padding: 2.2rem;
  overflow: hidden;
  transition: background .4s;
}.sc-tw .anodized-cell::before{
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at var(--cx,50%) var(--cy,50%), oklch(72% 0.18 85 / 0.06) 0%, transparent 60%);
  opacity: 0;
  transition: opacity .4s;
}.sc-tw .anodized-cell:hover{ background: var(--titanium-mid); }.sc-tw .anodized-cell:hover::before{ opacity: 1; }.sc-tw .anodized-cell.wide{ grid-column: 1 / -1; }.sc-tw .anodized-cell.accent{ background: oklch(16% 0.025 85); }.sc-tw .cell-icon{
  width: 36px; height: 36px;
  border-radius: 6px;
  background: oklch(100% 0 0 / 0.04);
  border: 1px solid var(--glass-border);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.4rem;
  font-size: 0.85rem;
}.sc-tw .cell-label{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--amber-dim);
  margin-bottom: 0.7rem;
}.sc-tw .cell-title{
  font-size: 1.05rem;
  font-weight: 500;
  letter-spacing: -0.02em;
  margin-bottom: 0.7rem;
  line-height: 1.2;
}.sc-tw .cell-body{
  font-size: 0.78rem;
  line-height: 1.75;
  color: var(--text-secondary);
  font-weight: 300;
}.sc-tw .cell-metric{
  font-family: 'Playfair Display', serif;
  font-size: 2.8rem;
  font-weight: 400;
  letter-spacing: -0.03em;
  color: var(--text-primary);
  line-height: 1;
  margin-bottom: 0.3rem;
}.sc-tw .cell-metric-unit{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.6rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-tertiary);
}.sc-tw .inner-shadow-card{
  box-shadow:
    inset 0 1px 0 oklch(100% 0 0 / 0.06),
    inset 0 -1px 0 oklch(0% 0 0 / 0.3),
    inset 1px 0 0 oklch(100% 0 0 / 0.04),
    inset -1px 0 0 oklch(0% 0 0 / 0.2),
    0 4px 24px oklch(0% 0 0 / 0.4);
}.sc-tw .telemetry-bar{
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 1.2rem;
}.sc-tw .telem-row{
  display: flex;
  align-items: center;
  gap: 0.8rem;
  font-family: 'JetBrains Mono', monospace;
}.sc-tw .telem-key{ font-size: 0.58rem; color: var(--text-tertiary); letter-spacing: 0.1em; text-transform: uppercase; flex: 0 0 80px; }.sc-tw .telem-track{ flex: 1; height: 3px; background: oklch(100% 0 0 / 0.06); border-radius: 2px; overflow: hidden; }.sc-tw .telem-fill{ height: 100%; border-radius: 2px; background: linear-gradient(90deg, var(--cyan), var(--amber)); position: relative; }.sc-tw .telem-fill::after{ content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, transparent, oklch(100% 0 0 / 0.4), transparent); animation: shimmer-t 2.5s ease-in-out infinite; }
@keyframes shimmer-t {0%{ transform: translateX(-100%); }100%{ transform: translateX(100%); } }.sc-tw .telem-val{ font-size: 0.6rem; color: var(--amber); flex: 0 0 40px; text-align: right; }.sc-tw .assembly-section{
  padding: 8rem 0;
}.sc-tw .circuit-row{
  display: flex;
  flex-direction: column;
  gap: 1px;
  background: var(--glass-border);
  border: 1px solid var(--glass-border);
  border-radius: 6px;
  overflow: hidden;
  margin-top: 3.5rem;
}.sc-tw .circuit-item{
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 1.6rem 2rem;
  background: var(--titanium-base);
  position: relative;
  overflow: hidden;
  opacity: 0;
  transform: translateX(-20px);
  transition: background .3s, opacity .6s, transform .6s;
}.sc-tw .circuit-item.assembled{
  opacity: 1;
  transform: translateX(0);
}.sc-tw .circuit-item::after{
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 2px;
  background: linear-gradient(180deg, var(--amber), var(--cyan));
  box-shadow: 0 0 10px 2px var(--amber-glow);
  transform: scaleY(0);
  transform-origin: top;
  transition: transform .5s cubic-bezier(.16,1,.3,1);
}.sc-tw .circuit-item.assembled::after{ transform: scaleY(1); }.sc-tw .circuit-num{
  font-family: 'Playfair Display', serif;
  font-size: 2rem;
  font-weight: 400;
  color: oklch(100% 0 0 / 0.08);
  flex: 0 0 3rem;
  line-height: 1;
}.sc-tw .circuit-content{ flex: 1; }.sc-tw .circuit-title{
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  margin-bottom: 0.3rem;
}.sc-tw .circuit-desc{
  font-size: 0.75rem;
  color: var(--text-secondary);
  line-height: 1.6;
  font-weight: 300;
}.sc-tw .circuit-badge{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.55rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.3rem 0.8rem;
  border-radius: 100px;
  border: 1px solid var(--glass-border);
  color: var(--text-tertiary);
  white-space: nowrap;
  flex-shrink: 0;
}.sc-tw .circuit-badge.active{
  color: var(--amber);
  border-color: oklch(72% 0.18 85 / 0.3);
  background: oklch(72% 0.18 85 / 0.07);
  box-shadow: 0 0 12px var(--amber-glow);
}.sc-tw .ledger-section{
  padding: 8rem 0;
}.sc-tw .ledger-display{
  background: var(--titanium-base);
  border: 1px solid var(--glass-border);
  border-radius: 6px;
  overflow: hidden;
  margin-top: 3.5rem;
}.sc-tw .ledger-header{
  padding: 1.2rem 2rem;
  background: oklch(100% 0 0 / 0.02);
  border-bottom: 1px solid var(--glass-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}.sc-tw .ledger-title-bar{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-tertiary);
}.sc-tw .ledger-live{
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.55rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--amber);
}.sc-tw .pulse-dot{
  width: 5px; height: 5px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 8px 2px var(--amber-glow);
  animation: pulse-a 2s ease-in-out infinite;
}

@keyframes pulse-a {0%,100%{ opacity: 1; transform: scale(1); }50%{ opacity: 0.3; transform: scale(0.6); }
}.sc-tw .ledger-entries{
  display: flex;
  flex-direction: column;
}.sc-tw .ledger-entry{
  display: flex;
  align-items: center;
  padding: 1.1rem 2rem;
  border-bottom: 1px solid var(--glass-border);
  gap: 1.5rem;
  position: relative;
  overflow: hidden;
  transition: background .3s;
}.sc-tw .ledger-entry:last-child{ border-bottom: none; }.sc-tw .ledger-entry:hover{ background: oklch(100% 0 0 / 0.02); }.sc-tw .entry-icon{
  width: 32px; height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  flex-shrink: 0;
  border: 1px solid var(--glass-border);
  background: oklch(100% 0 0 / 0.04);
}.sc-tw .entry-merchant{ font-size: 0.82rem; font-weight: 500; }.sc-tw .entry-category{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.55rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-top: 0.2rem;
}.sc-tw .entry-amount{
  margin-left: auto;
  font-family: 'Playfair Display', serif;
  font-size: 1.05rem;
  font-weight: 400;
  letter-spacing: -0.01em;
}.sc-tw .entry-amount.debit{ color: var(--text-primary); }.sc-tw .entry-amount.credit{ color: var(--amber); }.sc-tw .entry-time{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.55rem;
  color: var(--text-tertiary);
  letter-spacing: 0.08em;
  flex-shrink: 0;
}.sc-tw .entry-stream{
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 1px;
  background: linear-gradient(180deg, transparent, var(--amber-dim), transparent);
  opacity: 0;
  transition: opacity .3s;
}.sc-tw .ledger-entry:hover .entry-stream{ opacity: 0.6; }.sc-tw .chart-area{
  padding: 1.5rem 2rem;
  border-top: 1px solid var(--glass-border);
}.sc-tw .chart-label{
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.55rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-bottom: 1rem;
}.sc-tw .sparkline-container{ position: relative; height: 60px; }.sc-tw .sparkline-container svg{ width: 100%; height: 100%; }.sc-tw .secure-section{
  padding: 8rem 0 12rem;
}.sc-tw .secure-grid{
